-- Limpieza del catálogo añadido con seed-categorias-3.sql: libros en una categoría que no les toca,
-- títulos con restos («(Saga 1)», «- 4ta Edicion», letras partidas), autores al revés («Williams, Stephen»)
-- y entradas que no son libros para leer (packs, manuales técnicos, leyes...).
-- Solo hace falta si YA ejecutaste seed-categorias-3.sql antes de esta corrección; si no, no pasa nada por
-- ejecutarlo igualmente. Ejecutar en Supabase: SQL Editor > New query > pegar y "Run". Se puede repetir.

-- Tildes guardadas como dos caracteres (letra + acento) -> forma normal
update public.catalog c set title = normalize(c.title, NFC), author = normalize(c.author, NFC)
where (c.title <> normalize(c.title, NFC) or c.author <> normalize(c.author, NFC))
  and not exists (select 1 from public.catalog d where d.id <> c.id and d.title = normalize(c.title, NFC) and d.author = normalize(c.author, NFC));

